package ghcredentials

import (
	"context"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"time"

	"github.com/devsy-org/devsy/pkg/log"
	"gopkg.in/yaml.v3"
)

const hostNoActiveAccounts = "no_active_accounts"

type Account struct {
	Host  string `json:"host"`
	User  string `json:"user"`
	Token string `json:"token"`
}

func HostAccounts(ctx context.Context) HostResult {
	binary, err := exec.LookPath("gh")
	if err != nil {
		return HostResult{Status: "gh_not_found"}
	}
	dir, err := ConfigDir()
	if err != nil {
		return HostResult{Status: "config_path_failed"}
	}
	probe, err := os.MkdirTemp("", "devsy-gh-host-")
	if err != nil {
		return HostResult{Status: "config_snapshot_" + errorKind(err)}
	}
	defer func() { _ = os.RemoveAll(probe) }()
	if err := copyConfigFiles(dir, probe); err != nil {
		return HostResult{Status: "config_snapshot_" + errorKind(err)}
	}
	b, err := readFile(filepath.Join(probe, hostsFile))
	if err != nil {
		return HostResult{Status: "config_read_" + errorKind(err)}
	}
	hosts, err := decode(b)
	if err != nil {
		return HostResult{Status: "config_decode_failed"}
	}
	return collectHostAccounts(ctx, binary, hosts, replaceEnv(os.Environ(), "GH_CONFIG_DIR", probe))
}

func collectHostAccounts(
	ctx context.Context,
	binary string,
	hosts *yaml.Node,
	env []string,
) HostResult {
	result := HostResult{Status: hostNoActiveAccounts}
	for i := 0; i+1 < len(hosts.Content); i += 2 {
		host := hosts.Content[i].Value
		u := get(hosts.Content[i+1], "user")
		if u == nil || u.Value == "" {
			log.Debugw("gh relay: host account unavailable", "host", host)
			continue
		}
		account, err := (Account{Host: host, User: u.Value}).resolveHostToken(ctx, binary, env)
		if err != nil {
			result.Status = "token_lookup_failed"
		} else if account.valid() {
			result.Accounts = append(result.Accounts, account)
		}
	}
	if len(result.Accounts) > 0 && result.Status == hostNoActiveAccounts {
		result.Status = "available"
	}
	return result
}

func (a Account) resolveHostToken(
	ctx context.Context,
	binary string,
	env []string,
) (Account, error) {
	token, err := resolveToken(ctx, binary, a.Host, env)
	if err != nil {
		if noTokenResult(err) {
			log.Debugw("gh relay: host account unavailable", "host", a.Host)
			return Account{}, nil
		}
		log.Warnw(
			"gh relay: host token lookup failed",
			"host",
			a.Host,
			"error_type",
			errorKind(err),
		)
		return Account{}, err
	}
	a.Token = REDACTED
	return a, nil
}

func resolveToken(ctx context.Context, binary, host string, env []string) (string, error) {
	ctx, cancel := context.WithTimeout(ctx, 3*time.Second)
	defer cancel()
	//nolint:gosec // binary is resolved from the user's PATH; host is one argument.
	cmd := exec.CommandContext(ctx, binary, "auth", "token", "--hostname", host)
	// Scope this to the lookup child: nested wrappers must not return forwarded
	// credentials as evidence of local authentication.
	cmd.Env = replaceEnv(env, authProbeEnv, "1")
	out, err := cmd.Output()
	if err != nil {
		if ctx.Err() != nil {
			return "", ctx.Err()
		}
		return "", err
	}
	return strings.TrimSpace(string(out)), nil
}
package agentcontainer

import (
	"context"
	"encoding/base64"
	"encoding/json"
	"errors"
	"fmt"
	"net"
	"os"
	"strconv"
	"syscall"

	"github.com/devsy-org/devsy/cmd/flags"
	"github.com/devsy-org/devsy/pkg/agent/tunnel"
	"github.com/devsy-org/devsy/pkg/agent/tunnelserver"
	"github.com/devsy-org/devsy/pkg/config"
	"github.com/devsy-org/devsy/pkg/credentials"
	devconfig "github.com/devsy-org/devsy/pkg/devcontainer/config"
	"github.com/devsy-org/devsy/pkg/dockercredentials"
	cliflags "github.com/devsy-org/devsy/pkg/flags"
	"github.com/devsy-org/devsy/pkg/flags/names"
	"github.com/devsy-org/devsy/pkg/ghcredentials"
	"github.com/devsy-org/devsy/pkg/gitcredentials"
	"github.com/devsy-org/devsy/pkg/gitsshsigning"
	"github.com/devsy-org/devsy/pkg/log"
	"github.com/devsy-org/devsy/pkg/netstat"
	"github.com/spf13/cobra"
)

// CredentialsServerCmd holds the cmd flags.
type CredentialsServerCmd struct {
	*flags.GlobalFlags

	User string

	ConfigureGitHelper    bool
	ConfigureGitHubHelper bool
	ConfigureDockerHelper bool

	ForwardPorts      bool
	GitUserSigningKey string
}

// NewCredentialsServerCmd creates a new command.
func NewCredentialsServerCmd(flags *flags.GlobalFlags) *cobra.Command {
	cmd := &CredentialsServerCmd{
		GlobalFlags: flags,
	}
	credentialsServerCmd := &cobra.Command{
		Use:   "credentials-server",
		Short: "Starts a credentials server",
		Args:  cobra.NoArgs,
		RunE: func(c *cobra.Command, args []string) error {
			port, err := credentials.GetPort()
			if err != nil {
				return err
			}

			return cmd.Run(c.Context(), port)
		},
	}
	cliflags.Add(
		credentialsServerCmd,
		cliflags.Bool(
			&cmd.ConfigureGitHubHelper,
			"configure-github-helper",
			false,
			"If true will configure GitHub CLI authentication forwarding",
		),
		cliflags.Bool(
			&cmd.ConfigureGitHelper,
			names.ConfigureGitHelper,
			false,
			"If true will configure git helper",
		),
		cliflags.Bool(
			&cmd.ConfigureDockerHelper,
			names.ConfigureDockerHelper,
			false,
			"If true will configure docker helper",
		),
		cliflags.Bool(
			&cmd.ForwardPorts,
			names.ForwardPorts,
			false,
			"If true will automatically try to forward open ports within the container",
		),
		cliflags.String(&cmd.GitUserSigningKey, names.GitUserSigningKey, "", ""),
		cliflags.String(&cmd.User, names.User, "", "The user to use"),
	)
	_ = credentialsServerCmd.MarkFlagRequired(names.User)

	return credentialsServerCmd
}

// Run runs the command logic.
func (cmd *CredentialsServerCmd) Run(ctx context.Context, port int) error {
	runCtx, cancel := context.WithCancel(ctx)
	defer cancel()

	ln, err := claimPort(port)
	if err != nil {
		if errors.Is(err, errPortOwnedByAnotherSession) {
			cmd.logPortOwnedByAnotherSession(ctx, port)
			return nil
		}
		return err
	}
	defer func() { _ = ln.Close() }()

	tunnelClient, err := tunnelserver.NewTunnelClient(os.Stdin, os.Stdout)
	if err != nil {
		return fmt.Errorf("error creating tunnel client: %w", err)
	}

	if _, err := tunnelClient.Ping(runCtx, &tunnel.Empty{}); err != nil {
		return fmt.Errorf("ping client: %w", err)
	}

	cmd.maybeForwardPorts(runCtx, tunnelClient)
	if cmd.ConfigureGitHubHelper {
		if err := ghcredentials.Install(port); err != nil {
			log.Warnf("GitHub CLI wrapper installation unavailable: %v", err)
		}
	}

	if err := cmd.configureDockerHelper(port); err != nil {
		return err
	}

	if err := configureGitUserLocally(runCtx, cmd.User, tunnelClient); err != nil {
		log.Warnf("error configuring git user: %v", err)
		return err
	}

	cleanupGitHelper, err := cmd.configureGitCredentialHelper(runCtx, port)
	if err != nil {
		return err
	}
	defer cleanupGitHelper()

	cleanupGitSigning := cmd.configureGitSigningKey()
	defer cleanupGitSigning()

	return credentials.RunCredentialsServerWithListener(runCtx, ln, tunnelClient, cmd.User)
}

// errPortOwnedByAnotherSession marks a bind failure as another session
// already owning the port, not a real error.
var errPortOwnedByAnotherSession = errors.New("credentials server port owned by another session")

// claimPort binds port and returns the listener, holding it exclusively so
// no other session can bind the same port until the caller closes it (or
// hands it to RunCredentialsServerWithListener). Only one session's
// credentials-server can hold this port at a time.
func claimPort(port int) (net.Listener, error) {
	addr := net.JoinHostPort("localhost", strconv.Itoa(port))
	ln, err := net.Listen("tcp", addr)
	if err != nil {
		if errors.Is(err, syscall.EADDRINUSE) {
			return nil, fmt.Errorf("%w: %w", errPortOwnedByAnotherSession, err)
		}
		return nil, fmt.Errorf("port %d not available: %w", port, err)
	}
	return ln, nil
}

func (cmd *CredentialsServerCmd) logPortOwnedByAnotherSession(ctx context.Context, port int) {
	owner, err := credentials.FetchOwner(ctx, port)
	switch {
	case err != nil:
		log.Debugf(
			"skipping credentials server for user %s: port %d is taken and its owner could not be determined: %v",
			cmd.User,
			port,
			err,
		)
	case owner == "" || owner == cmd.User:
		log.Debugf(
			"skipping credentials server for user %s: another session already provides it on port %d",
			cmd.User,
			port,
		)
	default:
		log.Warnf(
			"credentials server for user %s was not started: port %d is already owned by user %s's session; "+
				"git/docker/signing credential helpers for %s will not work until that session ends",
			cmd.User,
			port,
			owner,
			cmd.User,
		)
	}
}

func (cmd *CredentialsServerCmd) maybeForwardPorts(
	ctx context.Context,
	tunnelClient tunnel.TunnelClient,
