func RunServices(ctx context.Context, opts RunServicesOptions) error {
	exitAfterTimeout := getExitAfterTimeout(opts.DevsyConfig, opts.DisableIdleTimeout)

	fp := portForwardParams{
		containerClient:  opts.ContainerClient,
		extraPorts:       opts.ExtraPorts,
		exitAfterTimeout: exitAfterTimeout,
		extraListeners:   opts.ExtraListeners,
	}

	result, err := getContainerResult(ctx, fp)
	if err != nil {
		return err
	}
	forwardedPorts := forwardDevContainerPorts(ctx, fp, result)

	resolver := buildPortAttributeResolver(result)

	return retry.OnError(wait.Backoff{
		Steps:    maxRetrySteps,
		Duration: retryDuration,
		Factor:   retryFactor,
		Jitter:   retryJitter,
	}, func(err error) bool {
		return ctx.Err() == nil
	}, func() error {
		return runServicesIteration(ctx, opts, forwardedPorts, resolver)
	})
}

// buildPortAttributeResolver loads port attributes from the container result.
func buildPortAttributeResolver(result *config2.Result) PortAttributeResolver {
	if result == nil || result.MergedConfig == nil {
		return nil
	}
	mc := result.MergedConfig
	if len(mc.PortsAttributes) == 0 && mc.OtherPortsAttributes == nil {
		return nil
	}
	return NewPortAttributeResolver(mc.PortsAttributes, mc.OtherPortsAttributes)

