		o.idleTimeout = d
	})
}

// WithMaxCallAttempts returns a DialOption that configures the maximum number
// of attempts per call (including retries and hedging) using the channel.
package server

import (
	"fmt"
	"io"
	"os"
	"os/exec"
	"sync"

	"github.com/devsy-org/devsy/pkg/log"
	"github.com/devsy-org/devsy/pkg/pty"
	"github.com/devsy-org/ssh"
)

// execNonPTY executes a command without a PTY, wiring stdout/stderr directly
// to the SSH session and using a StdinPipe to avoid blocking on stdin.
//
// Process group isolation (SysProcAttr) ensures child processes can be
// properly signaled on shutdown. SSH client signals are forwarded to the
// process.
func execNonPTY(sess ssh.Session, cmd *exec.Cmd) (err error) {
	log.Debugf("execute SSH server command")

	cmd.SysProcAttr = mergeCommandSysProcAttr(cmd.SysProcAttr)
	cmd.Stdout = sess
	cmd.Stderr = sess.Stderr()

	stdin, err := cmd.StdinPipe()
	if err != nil {
		return err
	}

	// Start before launching the stdin copier goroutine; if Start fails the
	// goroutine would block forever on a pipe with no reader.
	if err = cmd.Start(); err != nil {
		_ = stdin.Close()
		return fmt.Errorf("start command: %w", err)
	}

	go func() {
		_, _ = io.Copy(stdin, sess)
		_ = stdin.Close()
	}()

	sigs := make(chan ssh.Signal, 1)
	sess.Signals(sigs)
	defer func() {
		sess.Signals(nil)
		close(sigs)
	}()
	go func() {
		for sig := range sigs {
			forwardSignal(sig, cmd.Process)
		}
	}()

	return cmd.Wait()
}

// ptySession holds the state for a PTY-backed SSH session.
type ptySession struct {
	pc        pty.PTYCmd
	proc      pty.Process
	closeOnce sync.Once
	closeErr  error
"}

