package ssh

import (
	"context"
	"fmt"
	"io"
	"net"
	"os"
	"sync"
	"time"

	"github.com/devsy-org/devsy/pkg/transport"
	xssh "golang.org/x/crypto/ssh"
)

type SessionConnOptions struct {
	Command string
	Env     map[string]string
	Stderr  io.Writer
}

type sessionConn struct {
	stdin   io.WriteCloser
	stdout  io.Reader
	session *xssh.Session
	cancel  context.CancelFunc

	closeOnce sync.Once
	waitOnce  sync.Once
	waitDone  chan struct{}
	waitErr   error
}

// startedSession bundles a started SSH session together with its stdin/stdout
// pipes, which must be created before Session.Start is called.
type startedSession struct {
	session *xssh.Session
	stdin   io.WriteCloser
	stdout  io.Reader
}

// OpenSessionConn exposes a long-lived command on an existing SSH client as a
// managed connection. Closing it never closes the parent client.
func OpenSessionConn(
	ctx context.Context,
	client *xssh.Client,
	opts SessionConnOptions,
) (transport.ManagedConn, error) {
	if err := validateSessionConn(client, opts); err != nil {
		return nil, err
	}
	if ctx == nil {
		ctx = context.Background()
	}

	started, err := startSession(client, opts)
	if err != nil {
		return nil, err
	}

	sessionCtx, cancel := context.WithCancel(ctx)
	conn := &sessionConn{
		stdin: started.stdin, stdout: started.stdout, session: started.session, cancel: cancel,
		waitDone: make(chan struct{}),
	}
	go func() {
		<-sessionCtx.Done()
		_ = conn.Close()
	}()
	return conn, nil
}

func validateSessionConn(client *xssh.Client, opts SessionConnOptions) error {
	if client == nil {
		return fmt.Errorf("ssh client is required")
	}
	if opts.Command == "" {
		return fmt.Errorf("command is required")
	}
	return nil
}

func startSession(
	client *xssh.Client,
	opts SessionConnOptions,
) (*startedSession, error) {
	session, err := client.NewSession()
	if err != nil {
		return nil, fmt.Errorf("create ssh session: %w", err)
	}
	session.Stderr = opts.Stderr
	stdin, err := session.StdinPipe()
	if err != nil {
		_ = session.Close()
		return nil, fmt.Errorf("create ssh session stdin: %w", err)
	}
	stdout, err := session.StdoutPipe()
	if err != nil {
		_ = stdin.Close()
		_ = session.Close()
		return nil, fmt.Errorf("create ssh session stdout: %w", err)
	}
	for key, value := range opts.Env {
