func (c *sessionConn) Write(p []byte) (int, error) { return c.stdin.Write(p) }

func (c *sessionConn) Close() error {
	var err error
	c.closeOnce.Do(func() {
		c.cancel()
		if closeErr := c.stdin.Close(); closeErr != nil {
			err = closeErr
		}
		if closeErr := c.session.Close(); err == nil && closeErr != nil {
			err = closeErr
		}
	})
	return err
}

